#include "command_guard_support/production_headers.h"
#include <exception>
#include <thread>
#include <utility>

// Definitions normally supplied by the Client/Host executable.
std::atomic<bool> gbBridgeRunning{true};
bridge_util::Guid gUniqueIdentifier;
using Device = Bridge<BridgeId::Device>;
using Module = Bridge<BridgeId::Module>;
using bridge_util::Result;

namespace {
constexpr DWORD kWaitMs = 10000;
constexpr DWORD kProcessDeadlineMs = 120000;

void require(bool condition, const char* message) {
  if (!condition) { throw std::runtime_error(message); }
}

[[noreturn]] void failNow(const char* message) {
  std::fprintf(stderr, "Command guard IPC regression: %s (pid=%lu)\n",
    message, GetCurrentProcessId());
  std::fflush(stderr);
  // ExitProcess closes the Client's Job handle, killing an unfinished peer.
  // Exit immediately here rather than unwinding more transport/test state.
  ExitProcess(1);
}

class Handle {
  HANDLE m_value;
public:
  explicit Handle(HANDLE value) : m_value(value) {
    require(value != nullptr && value != INVALID_HANDLE_VALUE, "Win32 handle creation failed");
  }
  ~Handle() { CloseHandle(m_value); }
  Handle(const Handle&) = delete;
  Handle& operator=(const Handle&) = delete;
  HANDLE get() const { return m_value; }
};

class Watchdog {
  Handle m_done;
  std::thread m_worker;
public:
  Watchdog() : m_done(CreateEventW(nullptr, TRUE, FALSE, nullptr)), m_worker([this] {
    if (WaitForSingleObject(m_done.get(), kProcessDeadlineMs) != WAIT_OBJECT_0) {
      failNow("process deadline exceeded");
    }
  }) {}
  ~Watchdog() {
    SetEvent(m_done.get());
    m_worker.join();
  }
};

template<class F>
std::thread checkedThread(F&& work) {
  return std::thread([task = std::forward<F>(work)] {
    try { task(); }
    catch (const std::exception& error) { failNow(error.what()); }
    catch (...) { failNow("unknown worker failure"); }
  });
}

#ifdef REMIX_BRIDGE_SERVER
std::string ascii(const std::wstring& text) {
  std::string result;
  result.reserve(text.size());
  for (const wchar_t character : text) {
    require(character <= 0x7f, "non-ASCII transport identifier");
    result.push_back(static_cast<char>(character));
  }
  return result;
}
#endif

Handle namedEvent(const std::string& base, const char* suffix) {
  return Handle(CreateEventA(nullptr, TRUE, FALSE, (base + suffix).c_str()));
}

template<class B>
void initialize(const std::string& name) {
  // Actual eight-slot header rings and small data mappings force both wraps.
  B::init(name, 4096, 8, 512, 4096, 8, 512);
}

void initializeBoth(const std::string& base) {
  initialize<Device>(base + "Device");
  initialize<Module>(base + "Module");
  BridgeState::setServerState(BridgeState::ProcessState::Running);
  // Only the real queue wait/wake counters are enabled; external observers and
  // per-API timing remain disabled. This suite does not measure performance.
  l4d2_observation::memoryMonitoring = true;
}

template<class B>
void finishRead(const Header& header) {
  require(B::get_data_pos() == header.dataOffset, "header/data publication offset mismatch");
  const auto& reader = B::getReaderChannel();
  // Exercise the production protocol-3 consumed frontier and waiter wakeup.
  B::end_read_data();
  require(reader.control->consumed.load(std::memory_order_acquire) == reader.data->cursor(),
    "completed Host payload was not released to its writer");
}

uint32_t word(uint32_t uid, uint32_t producer, uint32_t sequence, uint32_t index) {
  return uid * 0x9e3779b9u ^ producer * 0x85ebca6bu ^ sequence * 0xc2b2ae35u ^ index;
}

uint32_t checksum(uint32_t uid, uint32_t producer, uint32_t sequence) {
  uint32_t sum = 0;
  for (uint32_t i = 0; i < sequence % 5 + 1; ++i) { sum += word(uid, producer, sequence, i); }
  return sum;
}

template<class B>
void publish(uint32_t producer, uint32_t count, bool idle) {
  for (uint32_t sequence = 0; sequence < count; ++sequence) {
    if (idle && sequence % 1024 == 0) { Sleep(15); }
    typename B::Command command(Commands::Bridge_DebugMessage, producer);
    const uint32_t uid = static_cast<uint32_t>(command.get_uid());
    const uint32_t words = sequence % 5 + 1;
    const uint32_t bytes = words * static_cast<uint32_t>(sizeof(uint32_t));
    command.send_many(producer, sequence, uid ^ 0xa55a5aa5u, words);
    std::array<uint32_t, 5> payload{};
    for (uint32_t i = 0; i < words; ++i) { payload[i] = word(uid, producer, sequence, i); }
    if (sequence % 2) {
      auto* destination = command.begin_data_blob(bytes);
      require(destination != nullptr, "blob reserve failed");
      std::memcpy(destination, payload.data(), bytes);
      command.end_data_blob();
    } else {
      command.send_data(bytes, payload.data());
    }
  }
}

template<class B>
void consumeAndRespond(uint32_t producers, uint32_t count) {
  std::vector<uint32_t> sequences(producers, 0);
  for (uint32_t expectedUid = 0; expectedUid < producers * count; ++expectedUid) {
    require(B::waitForCommand(Commands::Bridge_DebugMessage, kWaitMs) == Result::Success,
      "Host command wait failed");
    const auto header = B::pop_front();
    require(header.command == Commands::Bridge_DebugMessage, "wrong published opcode");
    require(B::begin_read_data() == Result::Success, "Host read batch failed");
    const uint32_t uid = B::get_data();
    const uint32_t producer = B::get_data(), sequence = B::get_data();
    const uint32_t token = B::get_data(), words = B::get_data();
    require(uid == expectedUid, "Client serialization UID order changed");
    require(producer < producers && header.pHandle == producer, "producer header mismatch");
    require(sequence == sequences[producer]++, "per-producer ordering changed");
    require(token == (uid ^ 0xa55a5aa5u) && words == sequence % 5 + 1,
      "scalar payload was torn or stale");
    void* blob = nullptr;
    const uint32_t bytes = B::get_data(&blob);
    require(bytes == words * sizeof(uint32_t) && blob != nullptr, "blob prefix mismatch");
    for (uint32_t i = 0; i < words; ++i) {
      require(static_cast<uint32_t*>(blob)[i] == word(uid, producer, sequence, i),
        "blob bytes were torn or stale");
    }
    finishRead<B>(header);
    typename B::Command response(Commands::Bridge_Response, uid);
    response.send_many(producer, sequence, token, checksum(uid, producer, sequence));
  }
  for (const auto sequence : sequences) { require(sequence == count, "Host lost a producer command"); }
}

template<class B>
void receiveResponses(uint32_t producers, uint32_t count) {
  std::vector<uint32_t> sequences(producers, 0);
  for (uint32_t expectedUid = 0; expectedUid < producers * count; ++expectedUid) {
    require(B::waitForCommand(Commands::Bridge_Response, kWaitMs, nullptr, true, expectedUid) == Result::Success,
      "Client response UID wait failed");
    // The Client owns the response Header until its complete payload has been
    // consumed. Production pop_front ends that read before publishing the pop.
    Result peekResult;
    const auto header = B::getReaderChannel().commands->peek(peekResult, kWaitMs);
    require(peekResult == Result::Success, "ready Client response disappeared");
    require(header.command == Commands::Bridge_Response && header.pHandle == expectedUid,
      "response publication ordering changed");
    require(B::begin_read_data() == Result::Success, "Client read batch failed");
    const uint32_t producer = B::get_data(), sequence = B::get_data();
    const uint32_t token = B::get_data(), sum = B::get_data();
    require(producer < producers && sequence == sequences[producer]++, "response producer ordering changed");
    require(token == (expectedUid ^ 0xa55a5aa5u) && sum == checksum(expectedUid, producer, sequence),
      "response payload mismatch");
    require(B::get_data_pos() == header.dataOffset, "response/header publication offset mismatch");
    const auto completed = B::pop_front();
    require(completed.command == header.command && completed.pHandle == header.pHandle,
      "Client popped a different response");
    const auto& reader = B::getReaderChannel();
    require(reader.control->consumed.load(std::memory_order_acquire) == reader.data->cursor(),
      "completed Client payload was not released to its writer");
  }
  for (const auto sequence : sequences) { require(sequence == count, "Client lost a response"); }
}

template<class B>
void requireDrained() {
  require(!B::getWriterChannel().pbCmdInProgress->load(std::memory_order_relaxed), "final guard not clear");
  require(B::getReaderChannel().commands->isEmpty() && B::getWriterChannel().commands->isEmpty(),
    "command queues not drained");
}

void requireWakeCoverage(bool idle) {
  const auto counters = l4d2_queue::counters.snapshot();
  require(counters.failures == 0 && counters.signalFailures == 0, "queue wait/wake API failed");
  if (idle) {
    require(counters.waits != 0 && counters.signals != 0, "idle run did not exercise queue wait and wake paths");
  }
}

#ifdef REMIX_BRIDGE_SERVER
void hostGuardChecks() {
  gbBridgeRunning = false;
  const auto devicePosition = Device::getWriterChannel().data->get_pos();
  const auto modulePosition = Module::getWriterChannel().data->get_pos();
  {
    Device::Command outer(Commands::Bridge_DebugMessage, 0);
    require(Device::getWriterChannel().pbCmdInProgress->load(std::memory_order_relaxed),
      "real Host guard was not set");
    bool rejected = false;
    try { Device::Command nested(Commands::Bridge_DebugMessage, 0); }
    catch (const std::runtime_error& error) {
      rejected = std::string(error.what()).find("Multiple active Command") != std::string::npos;
    }
    require(rejected, "real Host constructor did not reject nesting");
    require(Device::getWriterChannel().pbCmdInProgress->load(std::memory_order_relaxed),
      "nested failure cleared the outer guard");
    Module::Command otherQueue(Commands::Bridge_DebugMessage, 0);
    require(Module::getWriterChannel().pbCmdInProgress->load(std::memory_order_relaxed),
      "Module guard was not independent");
  }
  requireDrained<Device>();
  requireDrained<Module>();
  require(Device::getWriterChannel().data->get_pos() == devicePosition &&
      Module::getWriterChannel().data->get_pos() == modulePosition,
    "disabled Host command changed data positions");
}

int host(const std::wstring& guid, const std::string& base,
    uint32_t producers, uint32_t count, bool dual, bool idle) {
  auto mutableGuid = guid;
  auto* guidText = mutableGuid.data();
  require(gUniqueIdentifier.setGuid(&guidText), "cannot share GUID");
  initializeBoth(base);
  const auto ready = namedEvent(base, "Ready");
  const auto drained = namedEvent(base, "Drained");
  require(SetEvent(ready.get()) != FALSE, "cannot signal Host ready");
  std::thread module;
  if (dual) { module = checkedThread([&] { consumeAndRespond<Module>(1, count); }); }
  consumeAndRespond<Device>(producers, count);
  if (module.joinable()) { module.join(); }
  require(WaitForSingleObject(drained.get(), kWaitMs) == WAIT_OBJECT_0, "Client did not drain responses");
  requireWakeCoverage(idle);
  hostGuardChecks();
  return 0;
}
#endif

#ifdef REMIX_BRIDGE_CLIENT
int client(const std::wstring& peer, uint32_t producers, uint32_t count, bool dual, bool idle) {
  const auto base = "Local\\L4D2CommandGuard-" + std::to_string(GetCurrentProcessId()) + "-" +
    std::to_string(GetTickCount64());
  initializeBoth(base);
  const auto ready = namedEvent(base, "Ready");
  const auto drained = namedEvent(base, "Drained");
  const auto guid = gUniqueIdentifier.toString();
  const std::wstring baseWide(base.begin(), base.end()), guidWide(guid.begin(), guid.end());
  std::wstring command = L"\"" + peer + L"\" --host " + guidWide + L" " + baseWide + L" " +
    std::to_wstring(producers) + L" " + std::to_wstring(count) + L" " + std::to_wstring(dual) +
    L" " + std::to_wstring(idle);

  Handle job(CreateJobObjectW(nullptr, nullptr));
  JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};
  limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
  require(SetInformationJobObject(job.get(), JobObjectExtendedLimitInformation, &limits,
    static_cast<DWORD>(sizeof(limits))) != FALSE, "cannot configure peer cleanup Job");
  STARTUPINFOW startup{};
  startup.cb = static_cast<DWORD>(sizeof(startup));
  PROCESS_INFORMATION child{};
  require(CreateProcessW(peer.c_str(), command.data(), nullptr, nullptr, FALSE,
    CREATE_NO_WINDOW | CREATE_SUSPENDED, nullptr, nullptr, &startup, &child) != FALSE, "Host launch failed");
  Handle process(child.hProcess), initialThread(child.hThread);
  if (!AssignProcessToJobObject(job.get(), process.get())) {
    TerminateProcess(process.get(), 1);
    require(false, "cannot attach Host to cleanup Job");
  }
  require(ResumeThread(initialThread.get()) != static_cast<DWORD>(-1), "cannot start Host");
  const HANDLE readyOrExit[] = {ready.get(), process.get()};
  require(WaitForMultipleObjects(2, readyOrExit, FALSE, kWaitMs) == WAIT_OBJECT_0,
    "Host failed to initialize");

  if (idle) {
    // No producer has started and Host cannot respond. Exercise the actual
    // empty Bridge wait first, giving both processes an idle reader interval.
    require(Device::waitForCommand(Commands::Bridge_Response, 25) == Result::Timeout,
      "empty response queue did not time out");
    require(l4d2_queue::counters.snapshot().waits != 0, "empty queue did not enter the wait path");
  }
  auto replies = checkedThread([&] { receiveResponses<Device>(producers, count); });
  std::thread moduleReplies, moduleProducer;
  if (dual) {
    moduleReplies = checkedThread([&] { receiveResponses<Module>(1, count); });
    moduleProducer = checkedThread([&] { publish<Module>(0, count, idle); });
  }
  std::vector<std::thread> workers;
  workers.reserve(producers);
  for (uint32_t producer = 0; producer < producers; ++producer) {
    workers.emplace_back(checkedThread([&, producer] { publish<Device>(producer, count, idle); }));
  }
  for (auto& worker : workers) { worker.join(); }
  replies.join();
  if (dual) { moduleProducer.join(); moduleReplies.join(); }
  require(SetEvent(drained.get()) != FALSE, "cannot signal drained response queues");
  require(WaitForSingleObject(process.get(), kWaitMs) == WAIT_OBJECT_0, "Host did not finish");
  DWORD exitCode = 1;
  require(GetExitCodeProcess(process.get(), &exitCode) != FALSE && exitCode == 0, "Host checks failed");
  requireDrained<Device>();
  requireDrained<Module>();
  requireWakeCoverage(idle);

  // Same-thread Client nesting is deliberately excluded: the nonrecursive
  // channel mutex is acquired before its guard, so such misuse already hangs.
  // Consecutive disabled Commands do verify normal guard cleanup and unlock.
  gbBridgeRunning = false;
  const auto position = Device::getWriterChannel().data->get_pos();
  for (unsigned repeat = 0; repeat < 2; ++repeat) {
    Device::Command disabled(Commands::Bridge_DebugMessage, 0);
    require(Device::getWriterChannel().pbCmdInProgress->load(std::memory_order_relaxed),
      "disabled Client constructor did not set the guard");
    disabled.send_data(123);
  }
  requireDrained<Device>();
  require(Device::getWriterChannel().data->get_pos() == position, "disabled Client command changed data position");
  const auto counters = l4d2_queue::counters.snapshot();
  const uint32_t requests = (producers + (dual ? 1u : 0u)) * count;
  std::printf("{\"pass\":true,\"producers\":%u,\"commands_per_producer\":%u,"
    "\"dual_queue\":%s,\"idle_bursts\":%s,\"request_response_pairs\":%u,"
    "\"command_publications\":%u,\"client_wait_events\":%llu,\"client_wake_signals\":%llu}\n",
    producers, count, dual ? "true" : "false", idle ? "true" : "false", requests, requests * 2,
    static_cast<unsigned long long>(counters.waits), static_cast<unsigned long long>(counters.signals));
  return 0;
}
#endif
} // namespace

int wmain(int argc, wchar_t** argv) {
  SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
  std::set_terminate([] {
    if (const auto error = std::current_exception()) {
      try { std::rethrow_exception(error); }
      catch (const std::exception& exception) { failNow(exception.what()); }
      catch (...) {}
    }
    failNow("unexpected termination");
  });
  try {
    Watchdog watchdog;
#ifdef REMIX_BRIDGE_SERVER
    require(argc == 8 && std::wstring(argv[1]) == L"--host", "x64 executable must run as Host");
    const auto producers = static_cast<uint32_t>(std::stoul(argv[4]));
    const auto count = static_cast<uint32_t>(std::stoul(argv[5]));
    require(producers >= 1 && producers <= 4 && count >= 1 && count <= 20000, "invalid Host workload");
    return host(argv[2], ascii(argv[3]), producers, count,
      std::stoul(argv[6]) != 0, std::stoul(argv[7]) != 0);
#else
    require(argc == 6, "usage: command-guard-x86 host.exe producers count dual idle");
    const auto producers = static_cast<uint32_t>(std::stoul(argv[2]));
    const auto count = static_cast<uint32_t>(std::stoul(argv[3]));
    require(producers >= 1 && producers <= 4 && count >= 1 && count <= 20000, "invalid Client workload");
    return client(argv[1], producers, count, std::stoul(argv[4]) != 0, std::stoul(argv[5]) != 0);
#endif
  } catch (const std::exception& error) { failNow(error.what()); }
}
